"use client";

import * as React from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { DayPicker, formatDay as defaultFormatDay, labelDayButton as defaultLabelDayButton } from "react-day-picker";
import { useDirection } from "@radix-ui/react-direction";
import { cn } from "@/lib/utils";
import { buttonVariants } from "@/components/ui/button";

export type CalendarProps = React.ComponentProps<typeof DayPicker>;

/**
 * Direction: the navigation buttons sit on the inline start/end and range ends round their inline-start/end
 * corners, so the grid, the buttons and a selected range mirror together under RTL. Inside a
 * `KinetixDirectionProvider dir="rtl"` the calendar also swaps the chevrons and passes `dir` to
 * react-day-picker, which makes ArrowLeft/ArrowRight follow the mirrored grid. Without a provider the
 * direction is only known from the DOM, so `dir` is left unset rather than forced to "ltr" — the library's
 * RTL rule (RTL.md) is to wrap the app in the provider.
 */
function Calendar({ className, classNames, showOutsideDays = true, dir, labels, ...props }: CalendarProps) {
  const contextDir = useDirection();
  const resolvedDir = dir ?? (contextDir === "rtl" ? "rtl" : undefined);
  /**
   * A day button's name starts with the number it shows (WCAG 2.5.3, Label in Name). react-day-picker's
   * default name is the long date alone — "Sunday, March 1st, 2026" — which never contains the visible "1"
   * as a word, so a speech-input user saying "click 1" matches nothing. The visible text comes from the same
   * `formatDay` that renders the button, so the two cannot disagree in any locale; the long date, "Today" and
   * "selected" stay after it. A `labels.labelDayButton` the consumer passes wins unchanged.
   */
  const formatDay = props.formatters?.formatDay ?? defaultFormatDay;
  const labelDayButton: typeof defaultLabelDayButton = (date, modifiers, options, dateLib) =>
    `${formatDay(date, options, dateLib)}, ${defaultLabelDayButton(date, modifiers, options, dateLib)}`;
  return (
    <DayPicker
      dir={resolvedDir}
      labels={{ labelDayButton, ...labels }}
      showOutsideDays={showOutsideDays}
      className={cn("p-3 font-sans", className)}
      classNames={{
        months: "flex flex-col sm:flex-row gap-2",
        month: "flex flex-col gap-4",
        month_caption: "flex justify-center pt-1 relative items-center w-full",
        caption_label: "text-sm font-medium",
        nav: "flex items-center gap-1",
        // Resting-dim/hover-brighten nav icons — numerically the disabled
        // value (0.5) but not a disabled state, so left as a literal rather
        // than forced into --opacity-disabled or --opacity-muted (0.7, which
        // would change the rendered value).
        button_previous: cn(
          buttonVariants({ variant: "Outline", size: "icon" }),
          "absolute start-1 size-7 bg-transparent p-0 opacity-50 hover:opacity-visible",
        ),
        button_next: cn(
          buttonVariants({ variant: "Outline", size: "icon" }),
          "absolute end-1 size-7 bg-transparent p-0 opacity-50 hover:opacity-visible",
        ),
        month_grid: "w-full border-collapse",
        weekdays: "flex",
        weekday: "text-muted-foreground rounded-md w-8 font-normal text-[0.8rem]",
        week: "flex w-full mt-2",
        // Selection state (aria-selected/data-selected) lands on the day cell
        // itself in v10 (not a nested button), so the cell owns the
        // accent background + corner rounding and hands the primary-colored
        // "selected" circle down to `day_button` via a `group` class.
        day: cn(
          "group relative p-0 text-center text-sm focus-within:relative focus-within:z-focus aria-selected:bg-accent",
          props.mode === "range" ? "" : "aria-selected:rounded-md",
        ),
        day_button: cn(
          buttonVariants({ variant: "Ghost", size: "icon" }),
          "size-8 p-0 font-normal group-aria-selected:opacity-visible group-data-[selected=true]:bg-action group-data-[selected=true]:text-action-foreground group-data-[selected=true]:hover:bg-action group-data-[selected=true]:hover:text-action-foreground group-data-[selected=true]:focus:bg-action group-data-[selected=true]:focus:text-action-foreground",
        ),
        range_start: "day-range-start rounded-s-md",
        range_end: "day-range-end rounded-e-md",
        range_middle: "aria-selected:bg-accent aria-selected:text-accent-foreground",
        today: "bg-accent text-accent-foreground",
        outside: "day-outside text-muted-foreground aria-selected:text-muted-foreground",
        disabled: "text-muted-foreground opacity-disabled",
        hidden: "invisible",
        ...classNames,
      }}
      components={{
        // react-day-picker's default Nav always asks for "left" on previous and "right" on next; under RTL the
        // previous button is on the right, so its chevron must point right (toward the inline start).
        Chevron: ({ orientation, className: chevronClassName }) =>
          (orientation === "right") !== (resolvedDir === "rtl") ? (
            <ChevronRight className={cn("size-4", chevronClassName)} />
          ) : (
            <ChevronLeft className={cn("size-4", chevronClassName)} />
          ),
      }}
      {...props}
    />
  );
}
Calendar.displayName = "Calendar";

export { Calendar };

import { type ClassValue, clsx } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

// The Material type-scale utilities (`text-label-md`, `text-body-sm`, …) come
// from `fontSize` in tailwind.config.ts. Without this, tailwind-merge reads them
// as text *colours* and drops a real colour class (`text-primary-foreground`).
const twMerge = extendTailwindMerge({
  extend: {
    classGroups: {
      "font-size": [
        {
          text: [
            "display-lg", "display-md", "display-sm",
            "headline-lg", "headline-md", "headline-sm",
            "title-lg", "title-md", "title-sm", "title-dialog",
            "label-lg", "label-md", "label-sm",
            "body-lg", "body-md", "body-sm",
          ],
        },
      ],
    },
  },
});

/** Merges Tailwind class names, resolving conflicts (clsx + tailwind-merge). */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Keeps the keyboard somewhere useful when a control removes the row it lives in.
 *
 * A remove button inside a chip or a list row destroys itself. Nothing then holds focus, so the
 * browser drops it on `<body>` and the next Tab starts again from the top of the document — a
 * keyboard user clearing three chips is sent back to the beginning after each one.
 *
 * Call this from the removing control's own handler, with the control and a selector that matches
 * one peer per removable row. The surviving peer is chosen BEFORE the removal, from document order:
 * the next row's control, or the previous one when the last row goes. It is focused once the
 * removal has actually happened AND left the keyboard stranded — so a handler
 * that removes nothing, or that moves focus somewhere of its own, keeps the focus it chose.
 *
 * @param trigger the control that was activated
 * @param peerSelector a selector matching the equivalent control on every row, e.g. "[data-kx-remove]"
 * @param options.scope where to look for peers; defaults to the trigger's parent list or its document
 * @param options.fallback where to go when no row survives — a chip group's own input, say
 *
 * Limit: the removal is expected to commit within a microtask or the next animation frame, which is
 * what a React state update from a click does. A removal awaited behind a network call lands later
 * than that, and its focus is the caller's to manage.
 */
export function focusAfterRemoval(
  trigger: HTMLElement | null | undefined,
  peerSelector: string,
  options: { scope?: HTMLElement | null; fallback?: HTMLElement | null } = {},
): void {
  if (!trigger?.isConnected) return;
  const scope = options.scope ?? trigger.closest("ul, ol, [data-kx-removable-group]") ?? trigger.ownerDocument.body;
  const peers = Array.from(scope.querySelectorAll<HTMLElement>(peerSelector));
  const here = peers.indexOf(trigger);
  const survivor = here < 0 ? null : (peers[here + 1] ?? peers[here - 1] ?? null);
  const target = survivor ?? options.fallback ?? null;
  if (!target) return;

  const settle = () => {
    // The trigger is still there: nothing was removed, so nothing should move.
    if (trigger.isConnected) return false;
    // And step in only where the removal actually stranded the keyboard. A handler that moved focus
    // somewhere of its own — the input a chip group is typed into, say — made a deliberate choice,
    // and that choice wins. Stranded means focus fell back to the document, which is what a browser
    // does when the focused element is taken out of the tree.
    const doc = trigger.ownerDocument;
    const active = doc.activeElement;
    const stranded = !active || active === doc.body || active === doc.documentElement || !active.isConnected;
    if (!stranded) return true;
    if (target.isConnected) target.focus();
    return true;
  };
  queueMicrotask(() => {
    if (settle()) return;
    if (typeof requestAnimationFrame === "function") requestAnimationFrame(settle);
  });
}
